// Normalize items from 3 RSS sources into a single schema
const items = $input.all();

function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&laquo;/g, '«').replace(/&raquo;/g, '»')
    .replace(/&quot;/g, '"')
    .replace(/&#8217;/g, "'").replace(/&#8220;/g, '"').replace(/&#8221;/g, '"')
    .replace(/&#8230;/g, '...').replace(/&amp;/g, '&')
    .replace(/&ndash;/g, '–').replace(/&mdash;/g, '—')
    .replace(/\s+/g, ' ')
    .trim();
}

const normalized = items.map(item => {
  const d = item.json;
  let source = 'Unknown';
  if (d.link) {
    if (d.link.includes('techcrunch.com')) source = 'TechCrunch AI';
    else if (d.link.includes('theverge.com')) source = 'The Verge AI';
    else if (d.link.includes('huggingface.co')) source = 'HuggingFace';
  }

  const content = stripHtml(d.content || d.contentSnippet || d.summary || '');

  return {
    json: {
      title: (d.title || '').trim(),
      link: d.link,
      content: content.slice(0, 1500),
      published_at: d.pubDate || d.isoDate || new Date().toISOString(),
      source: source,
    }
  };
});

return normalized.filter(item =>
  item.json.title && item.json.title.length > 10 && item.json.link
);

// Filter out URLs already in Google Sheets
// SHEETS_CSV_URL must point to "Publish to web" CSV of the digest tab.
const SHEETS_CSV_URL = 'YOUR_PUBLISHED_SHEETS_CSV_URL';

const items = $input.all();

let processedUrls = new Set();

try {
  const csv = await this.helpers.httpRequest({
    method: 'GET',
    url: SHEETS_CSV_URL,
    json: false,
  });

  const lines = String(csv).split('\n');
  // First column = run_date, second = url
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(',');
    if (cols.length >= 2) {
      const url = cols[1].replace(/^"|"$/g, '').trim();
      if (url) processedUrls.add(url);
    }
  }
} catch (e) {
  console.log('Could not fetch processed URLs:', e.message);
}

const newItems = items.filter(item => !processedUrls.has(item.json.link));
console.log(`Total: ${items.length}, already in Sheets: ${processedUrls.size}, new: ${newItems.length}`);

return newItems;

// Generate OpenAI embedding for the current news item
const OPENAI_API_KEY = 'YOUR_OPENAI_API_KEY';
const news = $input.item.json;

const queryText = `${news.title}. ${news.content}`.slice(0, 2000);

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/embeddings',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${OPENAI_API_KEY}`,
  },
  body: {
    model: 'text-embedding-3-small',
    input: queryText,
  },
  json: true,
});

return {
  json: {
    ...news,
    embedding: resp.data[0].embedding,
    embed_query: queryText,
  }
};

// Anti-duplicate: search archive for similar news in last 30 days
const SUPABASE_URL = 'YOUR_SUPABASE_PROJECT_URL';
const SUPABASE_KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';

const news = $input.item.json;

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/rpc/match_news_archive`,
  headers: {
    'Content-Type': 'application/json',
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${SUPABASE_KEY}`,
  },
  body: {
    query_embedding: news.embedding,
    days_back: 30,
    match_threshold: 0.85,
    match_count: 3,
  },
  json: true,
});

const matches = resp || [];
const isDuplicate = matches.length > 0;

return {
  json: {
    ...news,
    is_duplicate: isDuplicate,
    duplicate_match: isDuplicate ? {
      url: matches[0].url,
      title: matches[0].title,
      similarity: Number(matches[0].similarity).toFixed(3),
      published_at: matches[0].published_at,
    } : null,
  }
};

// Parse JSON output from LLM, merge with news data
const llmOutput = $json.output || '';
const news = $('Archive Lookup').item.json;

let parsed;
try {
  // Strip optional ```json fences
  const cleaned = llmOutput
    .replace(/^```json\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return {
    json: {
      ...news,
      llm_error: e.message,
      raw_output: llmOutput,
      category: 'Other',
      summary: news.content.slice(0, 200),
      importance: 'low',
    }
  };
}

return {
  json: {
    title: news.title,
    link: news.link,
    source: news.source,
    published_at: news.published_at,
    embedding: news.embedding,
    category: parsed.category || 'Other',
    summary: parsed.summary || '',
    importance: parsed.importance || 'low',
  }
};

// Insert processed news into archive (for future anti-duplicate checks)
const SUPABASE_URL = 'YOUR_SUPABASE_PROJECT_URL';
const SUPABASE_KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';

const news = $input.item.json;

await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/news_archive`,
  headers: {
    'Content-Type': 'application/json',
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${SUPABASE_KEY}`,
    'Prefer': 'return=minimal',
  },
  body: {
    url: news.link,
    title: news.title,
    source: news.source,
    category: news.category,
    summary: news.summary,
    importance: news.importance,
    published_at: news.published_at,
    embedding: news.embedding,
  },
  json: true,
});

// Drop embedding from passed-along payload (Sheets doesn't need 1536 numbers)
const { embedding, ...rest } = news;
return { json: rest };
